#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/mise/tasks/updateall.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Upgrade all tools managed in the system"
# MISE depends=["global:init"]
# MISE hide=true
# MISE dir="~"
# MISE tools={uv="latest", python="3.14"}

# USAGE flag "-f --force" help="Run the weekly steps (macOS settings, power profile) even if they ran less than a week ago"

import os
import pathlib
import shutil
import subprocess
import sys
import time

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402

# Weekly steps run when the stamp is missing or over a week old. The stamp
# lives in /tmp on purpose: macOS clears it on reboot, and a macOS update (which
# resets these settings) always reboots, so the first updateall after an update
# re-applies them regardless of the week.
WEEKLY_STAMP = "/tmp/mise-updateall-weekly.stamp"
ONE_WEEK_SECONDS = 7 * 24 * 60 * 60


def exit_code(rc):
  """The exit code of the shell for a return code of subprocess: a process
  that a signal stopped gives 128 plus the signal number."""
  return 128 - rc if rc < 0 else rc


def run(*cmd, **kwargs):
  """Run the command. When it fails, stop the task with its code."""
  rc = subprocess.run(cmd, check=False, **kwargs).returncode
  if rc:
    sys.exit(exit_code(rc))


def run_task_if_exists(task, *args):
  """Run the mise task when it exists. When it fails, stop the task with its
  code."""
  rc = helpers.run_task_if_exists(task, *args)
  if rc:
    sys.exit(exit_code(rc))


def main():
  run_weekly = True
  if os.environ.get("usage_force", "false") == "true":
    try:
      os.remove(WEEKLY_STAMP)
    except FileNotFoundError:
      pass
  elif os.path.isfile(WEEKLY_STAMP):
    elapsed = int(time.time()) - int(os.stat(WEEKLY_STAMP).st_mtime)
    if elapsed < ONE_WEEK_SECONDS:
      run_weekly = False
      # int() of the division cuts toward zero, as the arithmetic of the shell.
      hours = int(elapsed / 3600)
      helpers.print_header(f"Skipping weekly steps — last run {hours}h ago; use --force to override.")

  # Kill keyboxd (gpg) to ensure that stale keys are refreshed
  # gpgconf --kill all || true

  # Upgrade mise first to ensure we have the latest features and fixes. mise
  # manages its own formula ([bootstrap.packages]).
  helpers.print_header("Upgrading MISE ...")
  run("mise", "self-update", "--yes")

  # Render the Mac tools into $HOME. The sync installs nothing: the
  # `mise bootstrap` steps follow below. Exit 4: the rest needs a new terminal.
  helpers.print_subheader("Rendering the Mac tools ...")
  configs_rc = exit_code(subprocess.run(["mise", "run", "updateall:configs"], check=False).returncode)
  if configs_rc == 4:
    helpers.print_warn("open a new terminal, then run: mise run updateall")
    sys.exit(4)
  elif configs_rc != 0:
    helpers.print_error(f"updateall:configs failed (exit {configs_rc})")
    sys.exit(configs_rc)

  # Install & upgrade mise
  helpers.print_subheader("Install MISE tools ...")
  run("mise", "install", "--yes", "--include-task-tools", "--jobs", "10")

  helpers.print_subheader("Upgrading mise tools ...")
  run("mise", "upgrade", "--yes", "--jobs", "10")

  # Prune all unused versions of tools
  helpers.print_subheader("Pruning unused versions of tools ...")
  run("mise", "prune", "--yes")

  # Update the plugins of the global dprint config (the dprint tool). The next
  # sync keeps the new versions.
  dprint_config = os.path.expanduser("~/.config/dprint/dprint.jsonc")
  if (
    os.path.isfile(dprint_config)
    and subprocess.run(
      ["mise", "x", "--", "which", "dprint"],
      check=False,
      stdout=subprocess.DEVNULL,
      stderr=subprocess.DEVNULL,
    ).returncode
    == 0
  ):
    helpers.print_subheader("Updating dprint plugins ...")
    run("mise", "x", "--", "dprint", "config", "update", "--yes", "--config", dprint_config)

  # Upgrade Homebrew and all installed packages (the homebrew tool), with the
  # GitHub token of fnox's brew profile when fnox is there
  if not helpers.task_exists("upgrade:brew"):
    helpers.print_warn("Skipping upgrade:brew: no such task (its tool is not selected)")
  elif shutil.which("fnox"):
    fnox_config = os.path.expanduser("~/.config/fnox/config.toml")
    run("fnox", "-c", fnox_config, "exec", "--profile", "brew", "--", "mise", "run", "upgrade:brew")
  else:
    helpers.print_warn("fnox is not on PATH: running upgrade:brew without its GitHub token")
    run("mise", "run", "upgrade:brew")

  helpers.print_subheader("Installing rest using mise ...")
  run("mise", "bootstrap", "--skip", "macos-defaults,packages", "--yes")

  # Reshim mise to ensure all tools are available
  helpers.print_subheader("Reshimming mise ...")
  run("mise", "reshim")

  # Run mise doctor
  helpers.print_subheader("Running mise doctor ...")
  run("mise", "doctor", "--quiet", "--silent", stdout=subprocess.DEVNULL)

  run_task_if_exists("upgrade:npm")

  run_task_if_exists("upgrade:ai")

  # Weekly, and last on purpose: this prompts for sudo (pmset/nvram) and restarts
  # Finder, Dock and ControlCenter, so everything above it is already done by
  # then. `files` re-checks /etc/pam.d/sudo_local (Touch ID for sudo), `defaults`
  # the macOS settings, `task` the pmset/nvram power profile.
  if run_weekly:
    # Apply macOS system settings
    helpers.print_header("Applying macOS system settings ...")
    run("mise", "bootstrap", "--only", "macos-defaults,defaults", "--yes")

    run("mise", "run", "upgrade:power")

    # Update the weekly stamp to indicate that the weekly steps have been run
    pathlib.Path(WEEKLY_STAMP).touch()

  # Upgrade macOS
  run("mise", "run", "upgrade:macos:download")

  # Clean up unnecessary .DS_Store files from the projects folder
  run_task_if_exists("cleanupDS", os.environ.get("PROJECTS_DIR", ""))

  # Start tailscale daemon
  run_task_if_exists("tailscale:daemon")

  helpers.print_header("Setup complete!")


if __name__ == "__main__":
  main()
